const money=(v,c='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency:c,maximumFractionDigits:2}).format(v);
const signed=v=>(v>=0?'+':'−')+money(Math.abs(v));
const pct=s=>(s.price/s.prev-1)*100;
const percent=v=>(v>=0?'+':'')+v.toFixed(1)+'%';
const toneClass=v=>v>=0?'positive':'negative';
const badge=(t,k='')=>`<span class="badge ${k}">${esc(t)}</span>`;
const link=(p,t,cls='text-button',symbol='')=>`<a class="${cls}" href="#${p}${symbol?'/'+symbol:''}" ${t.replace(/<[^>]*>/g,'').trim()?'':`aria-label="Open ${titles[p]||p}${symbol?' for '+symbol:''}"`}>${t}</a>`;
const button=(a,t,cls='button',extra='')=>`<button class="${cls}" data-action="${a}" ${extra}>${t}</button>`;
const company=s=>`<div class="company"><span class="company-mark">${s.id.slice(0,2)}</span><span><strong class="ticker">${s.id}</strong><span class="company-name">${s.name}</span></span></div>`;
function heading(title,sub,actions='',date=''){return `<div class="page-heading"><div>${date?`<div class="date-label">${date}</div>`:''}<h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
const sectionHead=(title,action='',sub='')=>`<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
function tabs(key,items){const active=state.tab[key]||items[0];return `<div class="page-tabs" aria-label="${esc(key)} views">${items.map(t=>`<button data-action="tab" data-key="${key}" data-value="${t}" class="${active===t?'active':''}" aria-pressed="${active===t}">${t}</button>`).join('')}</div>`;}
function spark(s){let a=s.points,min=Math.min(...a),max=Math.max(...a),coords=a.map((v,i)=>`${i*110/(a.length-1)},${29-(v-min)/(max-min||1)*24}`).join(' ');return `<svg class="spark" viewBox="0 0 110 35" role="img" aria-label="${s.id} price trend, ending ${money(s.price)}"><polyline points="${coords}" fill="none" stroke="var(--green)" stroke-width="1.6"/></svg>`;}
function chart(s,{mini=false,bars=false,range=state.range,values=null,label=null}={}){
 let a=values||s.points;
 if(!values&&range!=='1D'){const end=s.price;a=Array.from({length:24},(_,i)=>+(end*(.72+i*.011)+Math.sin(i*.7)*end*.025).toFixed(3));a[a.length-1]=end;}
 const mobile=window.innerWidth<700;
 const w=mini?320:mobile?350:660,h=mini?155:bars?320:245,l=mini?4:43,r=mini?35:20,top=20,bottom=bars?207:h-38;
 const min=Math.min(...a),max=Math.max(...a),pad=(max-min||.08)*.16,lo=min-pad,hi=max+pad;
 const x=i=>l+i*(w-l-r)/Math.max(1,a.length-1),y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top);
 const pts=a.map((v,i)=>`${x(i)},${y(v)}`).join(' ');
 const grid=Array.from({length:4},(_,i)=>{let val=lo+(hi-lo)*i/3,yy=y(val);return `<line class="gridline" x1="${l}" y1="${yy}" x2="${w-r}" y2="${yy}"/>${!mini?`<text x="${l-8}" y="${yy+4}" text-anchor="end">${val.toFixed(2)}</text>`:''}`;}).join('');
 const counts=a.map((_,i)=>8+Math.round(Math.abs(Math.sin(i*1.3))*11)+(i>14?i*2:0));
 const barSvg=bars?`<text x="${l}" y="235">${range==='1D'?'Posts / 5 min':range==='1W'?'Posts / 6 hours':'Posts / day'}</text>${counts.map((v,i)=>`<rect class="chatter-bar" x="${x(i)-3}" y="${291-v*.65}" width="6" height="${v*.65}" rx="1"/>`).join('')}`:'';
 const tickLabels=values?Array.from({length:4},(_,i)=>{const end=[840,858,875,900,930][state.replay],m=Math.round(810+(end-810)*i/3);return Math.floor(m/60)+':'+String(m%60).padStart(2,'0');}):range==='1D'?['13:30','14:10','14:50','15:30']:range==='1W'?['Sep 3','Sep 5','Sep 7','Sep 9']:['Aug 10','Aug 20','Aug 30','Sep 9'];
 const endY=y(a.at(-1));
 return `<div class="chart-container"><svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label||s.name+' sample price chart in USD')}"><title>${esc(label||s.name+' price')} — fictional data</title>${grid}<polyline class="price-line" points="${pts}"/><circle cx="${x(a.length-1)}" cy="${endY}" r="3" fill="var(--green)"/>${mini?`<text x="${w-3}" y="${endY+4}" text-anchor="end">${a.at(-1).toFixed(2)}</text>`:''}${barSvg}${[0,.33,.66,1].map((v,i)=>`<text x="${l+(w-l-r)*v}" y="${h-7}" text-anchor="${i===0?'start':i===3?'end':'middle'}">${tickLabels[i]}</text>`).join('')}</svg>${!mini?`<label class="chart-readout" style="display:flex;gap:12px;align-items:center">Inspect price<input type="range" min="0" max="${a.length-1}" value="${a.length-1}" data-chart-prices="${a.join(',')}" aria-label="Inspect chart price point" style="accent-color:var(--green);min-width:60px;flex:1"><output class="number">${money(a.at(-1))}</output></label>`:''}</div>`;
}
function notice(){return state.scenario==='delayed'?`<div class="notice amber">${icon('clock')}<div><strong>Some evidence is behind the market.</strong><p>Sample quotes are 15 minutes old; one social source last updated at 15:10. Rankings may be incomplete.</p></div></div>`:'';}
function empty(title,copy,page='combined',cta='Explore the radar'){return `<div class="empty">${icon('radar')}<h2>${title}</h2><p>${copy}</p>${link(page,cta,'button primary')}</div>`;}
function visibleStocks(){return stocks.filter(s=>(!state.filter||(s.name+' '+s.id).toLowerCase().includes(state.filter.toLowerCase()))&&(!state.broker||s.available==='available')&&(state.segment!=='Under $1'||s.price<1));}
function filters(){return `<div class="filters"><input id="candidate-filter" class="inline-search" type="search" aria-label="Filter companies" placeholder="Filter companies…" value="${esc(state.filter)}"><select id="segment" aria-label="Stock universe"><option ${state.segment==='All sizes'?'selected':''}>All sizes</option><option ${state.segment==='Under $1'?'selected':''}>Under $1</option></select><label><input id="broker-filter" type="checkbox" ${state.broker?'checked':''}> Verified on Scalable</label><span class="spacer"></span><span class="small muted">Last hour / International</span></div>`;}
function emptyResults(){return `<div class="empty">${icon('search')}<h2>${state.broker?'No verified listings in this sample':'No matching companies'}</h2><p>${state.broker?'Unknown broker availability is kept separate from verified availability. Clear the filter to keep exploring.':'Try a different company name or a broader filter.'}</p>${button('clear-filters','Clear filters','button primary')}</div>`;}
function ledger(){let holdings={},realized=0,closed=[],curve=[0];const transactions=(state.account==='paper'?demo.paper:demo.trades).slice().sort((a,b)=>a.date.localeCompare(b.date)||a.id-b.id);
 for(const t of transactions){let h=holdings[t.symbol] ||= {qty:0,cost:0,strategy:t.strategy};if(t.side==='buy'){h.qty+=t.qty;h.cost+=t.qty*t.price+t.fee;h.strategy=t.strategy;}else if(h.qty>=t.qty){let basis=h.cost/h.qty*t.qty;const result=t.qty*t.price-t.fee-basis;h.qty-=t.qty;h.cost-=basis;realized+=result;closed.push({...t,result});curve.push(realized);}}
 let positions=Object.entries(holdings).filter(([,h])=>h.qty>.00001).map(([symbol,h])=>({...h,symbol,value:h.qty*stock(symbol).price,pnl:h.qty*stock(symbol).price-h.cost}));
 return {positions,realized,closed,curve,value:positions.reduce((s,p)=>s+p.value,0),unrealized:positions.reduce((s,p)=>s+p.pnl,0),transactions};
}
function watchRows(ids=demo.watch){return ids.map(id=>{let s=stock(id);return `<tr><td>${link('research',company(s),'',id)}</td><td class="number">${money(s.price)}<span class="table-sub">USD / sample venue</span></td><td class="number ${toneClass(pct(s))}">${percent(pct(s))}</td><td class="mobile-hide">${s.ratio?s.ratio+'× normal':'Building baseline'}</td><td class="table-trend">${spark(s)}</td><td class="align-right">${link('research',icon('chevron'),'text-button',id)}</td></tr>`;}).join('');}
function overview(){const s=stocks[0],l=ledger();return heading('Your market, in focus.','A clearer view of what changed, and what deserves a closer look.',link('combined','Explore the radar '+icon('arrow'),'button'),'Wednesday, 9 September / 15:42 Berlin')+notice()+`<div class="two-col"><div class="stack"><section class="panel panel-pad">${sectionHead('Since your last visit',badge('3 new developments'))}<article class="lead-story"><div>${badge('Interest spreading')}<h3>Kestrel Bio is finding a wider audience.</h3><p>42 independent authors are discussing the trial update. Attention is up 8.4×; the share price has moved ${percent(pct(s))}.</p>${link('research','Understand the signal '+icon('arrow'),'text-button','KSTR')}</div><div class="story-chart"><span class="ticker">KSTR <span class="muted">/ Kestrel Bio</span></span><div class="story-price number"><strong>$1.84</strong><span class="positive">${percent(pct(s))}</span></div>${chart(s,{mini:true,range:'1D'})}<div class="caption">USD / sample venue / price through 15:30</div></div></article><a class="compact-story" href="#research/NRLN"><span class="company-mark">NE</span><div><h3>Northline’s update is drawing mixed reactions.</h3><p>New coverage, but little agreement on what changes.</p></div>${icon('chevron')}</a><a class="compact-story" href="#research/ARDR"><span class="company-mark">AR</span><div><h3>Ardent’s attention spike needs a closer look.</h3><p>Two authors account for 71% of its discussion.</p></div>${icon('chevron')}</a></section><section>${sectionHead('On your watchlist',link('watchlist','All watched stocks '+icon('arrow')))}${state.scenario==='empty'?empty('Make this your market','Watch a company to see meaningful changes here.','research/KSTR','Find your first stock'):`<div class="table-wrap"><table><thead><tr><th>Company</th><th>Price</th><th>Today</th><th class="mobile-hide">Attention</th><th class="table-trend">Price trend</th><th></th></tr></thead><tbody>${watchRows()}</tbody></table></div>`}</section><section class="brief-note"><h3>Your research, connected.</h3><p>${state.horizon==='Intraday'?'Start with a signal, inspect the sources, and keep the reasoning with your trade.':'Look beyond the day’s discussion. Follow catalysts, persistent interest and the reasoning behind your longer-term holdings.'}</p></section></div><aside class="stack"><section class="panel panel-pad">${sectionHead('Your positions',link('portfolio',icon('arrow')))}<div class="small muted">Open holdings / USD</div><div class="portfolio-value number">${money(l.value)}</div><div class="small positive number">${signed(l.unrealized)} unrealized</div><div class="positions-mini wide-gap">${l.positions.map(p=>`<a class="mini-stat" href="#research/${p.symbol}"><span><strong>${p.symbol}</strong><span class="table-sub">${p.qty} shares</span></span><span class="number ${toneClass(p.pnl)}">${signed(p.pnl)}</span></a>`).join('')}</div><div class="caption">Sample manual account / after entry fees</div></section><section class="panel panel-pad">${sectionHead('Coming up')}<div class="event"><div class="event-date">SEP<strong>10</strong></div><div><h3>Northline Energy</h3><p>Operations call / 16:00 Berlin</p>${link('research','Open company','text-button','NRLN')}</div></div><div class="event"><div class="event-date">SEP<strong>14</strong></div><div><h3>Vela Materials</h3><p>Investor presentation / 14:30 Berlin</p>${link('research','Open company','text-button','VELA')}</div></div></section><div class="brief-note"><h3>A note for today</h3><p>More posts don’t always mean more independent interest. Source breadth matters when a small stock gets loud.</p></div></aside></div>`;}
function chatter(){const list=visibleStocks();return heading('Listen beyond the noise.','Find unusual human interest, then see who and what is behind it.',badge(state.horizon+' research'))+notice()+filters()+(state.scenario==='empty'?empty('A quiet window','No unusual discussion in this sample window. Your watched companies are still available.','watchlist','Open watchlist'):!list.length?emptyResults():`<section class="panel panel-pad">${sectionHead('Human chatter',`<span class="small muted">${list.length} companies</span>`,'Ranked by unusual attention, with independent voices kept in view.')}<div class="table-wrap"><table><thead><tr><th>Company</th><th>Attention</th><th>Authors</th><th class="mobile-hide">Sources</th><th class="mobile-hide">Tone</th><th>Price / today</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td>${link('research',company(s),'',s.id)}</td><td><strong>${s.ratio?s.ratio+'×':'—'}</strong><span class="table-sub">${s.ratio?'its normal rate':'3-day baseline'}</span></td><td>${s.authors}<span class="table-sub">${s.mentions} posts</span></td><td class="mobile-hide">${s.sources}<span class="table-sub">${s.sources===1?'Single source':'Independent venues'}</span></td><td class="mobile-hide">${s.tone}% positive<div class="sentiment"><span style="width:${s.tone}%"></span><span style="width:${100-s.tone-10}%"></span><span style="width:10%"></span></div></td><td class="number">${money(s.price)}<span class="table-sub ${toneClass(pct(s))}">${percent(pct(s))}</span></td><td>${link('research',icon('chevron'),'text-button',s.id)}</td></tr>`).join('')}</tbody></table></div><div class="summary-line"><span><strong>5</strong> companies in this sample</span><span>USD prices / sample venue</span><span>Baseline compares equivalent hourly windows</span></div></section><div class="two-col wide-gap"><section>${sectionHead('What stands out')}<div class="compact-story"><span class="company-mark">KB</span><div><h3>KSTR’s interest is broadening.</h3><p>The same topic is now appearing across three independent communities.</p></div>${link('research',icon('arrow'),'text-button','KSTR')}</div><div class="compact-story"><span class="company-mark">AR</span><div><h3>ARDR’s tone is positive, but concentrated.</h3><p>A positive post count alone would miss that two authors dominate the conversation.</p></div>${link('research',icon('arrow'),'text-button','ARDR')}</div></section><aside class="brief-note"><h3>Reading the signal</h3><p>Attention measures how unusual discussion is. Authors and sources help you judge its breadth. Neither tells you whether the underlying claim is true.</p></aside></div>`);}
